import type { Source } from "./Core";
/**
 * Callbag operator that combines consecutive values from the same source
 * and emits a single accumulated value after the source completes.
 * Works on either pullable or listenable sources.
 *
 * Adapted from https://github.com/staltz/callbag-scan
 *
 * Marble diagram:
 *   " a b c |"
 *   {reduce((acc, d) => acc + d, "z")}
 *   " - - - zabc|"
 *
 * @param reducer A function that takes the accumulated value and
 *     the next value and returns a new accumulated value.
 * @param seed An initial seed value.
 *
 * @internal
 */
export declare const reduce: <T, E, U>(reducer: (acc: U, d: T) => U, seed: U) => (source: Source<T, E>) => Source<U, E>;
